            ctHash: uint256(hash),
            securityZone: 0,
            utype: utype,
            signature: signature
        });
    }

    function expectUtype(uint8 actual, uint8 expected) internal pure {
        if (actual != expected) {
            revert InvalidEncryptedInput(actual, expected);
        }
    }
}

